CREATE COLUMN TABLE "TEST_AP"."OWVT" ("Guid" NVARCHAR(40) NOT NULL , "Order" INTEGER CS_INT, "UserId" INTEGER CS_INT, "ViewType" NVARCHAR(50), "SubVType" NVARCHAR(50), "ViewId" NVARCHAR(50) DEFAULT '-1', "ObjName" NVARCHAR(50), "FltBarLout" NCLOB MEMORY THRESHOLD 1000, "SysFilter" NCLOB MEMORY THRESHOLD 1000, "UserFilter" NCLOB MEMORY THRESHOLD 1000, "CdtFilter" NCLOB MEMORY THRESHOLD 1000, "IsPublic" NVARCHAR(1) DEFAULT 'N', "IsSys" NVARCHAR(1) DEFAULT 'N', "Name" NVARCHAR(100), "Version" INTEGER CS_INT, "OvpCus" NCLOB MEMORY THRESHOLD 1000, "ChartCus" NCLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("Guid")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."OWVT" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$UserId$ViewType$ViewId$ObjName$','UserId','ViewType','ViewId','ObjName'));
CREATE INDEX "OWVT_GROUP" ON "TEST_AP"."OWVT" ( "UserId" ASC, "ViewType" ASC, "ViewId" ASC, "ObjName" ASC )